hdr(){ rg -io "^$1: [\w-]+" /tmp/h | awk '{print $2}'; }
echo "== CR-2 /64: 10 POSTs /api/personal-guide, new TCP connection each (connection: close), alternating two app instances = two isolates sharing one counter store; 10 different addresses in 2a09:bac1:57a0:18::/64 =="
for i in $(seq 1 10); do p=$((3917 + i % 2)); ip=$(printf "2a09:bac1:57a0:18::%x:%x" $((RANDOM)) $i); curl -s -o /dev/null -D /tmp/h -X POST localhost:$p/api/personal-guide -H "cf-connecting-ip: $ip" -H 'content-type: application/json' -H 'connection: close' --data '{"message":"What is a dividend?"}'; printf "%2d port=%s ip=%-32s %s x-ratelimit-key=%s remaining=%s store=%s retry-after=%s\n" $i $p $ip "$(head -1 /tmp/h | awk '{print $2}')" "$(hdr x-ratelimit-key)" "$(hdr x-ratelimit-remaining)" "$(hdr x-ratelimit-store)" "$(hdr retry-after)"; done
echo
echo "== CR-2 /48: 14 POSTs, each from a different /64 inside 2a09:bac5:4ec3::/48 =="
for i in $(seq 1 14); do p=$((3917 + i % 2)); ip=$(printf "2a09:bac5:4ec3:%x::50b:65" $((4096 + i*37))); curl -s -o /dev/null -D /tmp/h -X POST localhost:$p/api/personal-guide -H "cf-connecting-ip: $ip" -H 'content-type: application/json' -H 'connection: close' --data '{"message":"What is a dividend?"}'; printf "%2d port=%s ip=%-28s %s x-ratelimit-key=%s remaining=%s retry-after=%s\n" $i $p $ip "$(head -1 /tmp/h | awk '{print $2}')" "$(hdr x-ratelimit-key)" "$(hdr x-ratelimit-remaining)" "$(hdr retry-after)"; done
echo
echo "== CR-5: 12 failed sign-ins for one fake email (case varies), new connection each, 12 different /64s, alternating instances =="
for i in $(seq 1 12); do p=$((3917 + i % 2)); ip=$(printf "2001:db8:%x:%x::1" $((i*11)) $((i*7))); em=$([ $((i%2)) = 0 ] && echo "TT-RateLimit-Test3@Example.Invalid" || echo "tt-ratelimit-test3@example.invalid"); curl -s -o /dev/null -D /tmp/h -X POST localhost:$p/api/auth/sign-in/email -H "cf-connecting-ip: $ip" -H "origin: http://localhost:$p" -H 'content-type: application/json' -H 'connection: close' --data "{\"email\":\"$em\",\"password\":\"wrong-pass-$i\"}"; printf "%2d port=%s email=%-36s %s retry-after=%s\n" $i $p "$em" "$(head -1 /tmp/h | awk '{print $2}')" "$(hdr retry-after)"; done
